# --------------------------------------------------------------------------- published values
def snap_name(stamp_utc):
    s = datetime.fromisoformat(stamp_utc.replace("Z", "+00:00")).astimezone(timezone.utc)
    return f"snapshot-{s.strftime('%Y%m%dT%H%M%SZ')}.json"


def qvals(d, q):
    """One qubit's published values from a saved snapshot (properties.to_dict()): readout error, P(1|0), P(0|1), T1 and
    T2 (in the snapshot's units, us), each with its date."""
    out = {}
    for x in d["qubits"][q]:
        if x["name"] in QFIELDS:
            out[x["name"]] = x["value"]
            out[x["name"] + "_date"] = x["date"]
    return out


def table(d):
    return {str(q): {k: qvals(d, q).get(k) for k in QFIELDS} for q in QUBITS}


def published(p):
    """The sixteen qubits' published readout error, P(1|0) and P(0|1) from a live properties object."""
    def qp(q, name):
        try:
            v = p.qubit_property(q).get(name, (None,))[0]
            return None if v is None else float(v)
        except Exception:
            return None
    return {"readout_error_16": json.dumps({str(q): qp(q, "readout_error") for q in QUBITS}),
            "prob_meas1_prep0_16": json.dumps({str(q): qp(q, "prob_meas1_prep0") for q in QUBITS}),
            "prob_meas0_prep1_16": json.dumps({str(q): qp(q, "prob_meas0_prep1") for q in QUBITS})}


# --------------------------------------------------------------------------- the calibration record
def record_stamp(backend, kind, job_status="", refresh=True):
    """Read the backend's properties, save the snapshot if its stamp is new, compare it by value with the previous one
    (history 01's compare and other_changes), and append a row to stamps-61.csv."""
    STAMPS.mkdir(exist_ok=True)
    p = backend.properties(refresh=refresh)
    s = p.last_update_date.astimezone(timezone.utc)
    name = f"snapshot-{s.strftime('%Y%m%dT%H%M%SZ')}.json"
    path = STAMPS / name
    rows_p = HERE / "stamps-61.csv"
    rows = list(csv.DictReader(rows_p.open())) if rows_p.exists() else []
    seen = [r["snapshot"] for r in rows]
    new = name not in seen
    row = {"utc": now(), "kind": kind, "stamp_utc": s.strftime("%Y-%m-%dT%H:%M:%SZ"), "stamp_raw": str(p.last_update_date),
           "new_stamp": new, "job_status": job_status, "snapshot": name}
    if not path.exists():
        path.write_text(json.dumps(p.to_dict(), default=str, indent=1) + "\n")
    if new and seen:
        prev = STAMPS / seen[-1]
        c = TH.compare(TH.load(prev), TH.load(path))
        o = TH.other_changes(prev, path)
        row.update({"q_T1": c["q_T1"], "q_T2": c["q_T2"], "q_readout_error": c["q_readout_error"], "g1_any": c["g1_any"],
                    "cz_error": c["cz_error"], "cz_length": c["cz_length"], "other_values_changed": o["other_values_changed"],
                    "any_value_changed": o["any_value_changed"]})
    row.update(published(p))
    with rows_p.open("a", newline="") as fh:
        w = csv.DictWriter(fh, fieldnames=STAMP_FIELDS)
        if not rows:
            w.writeheader()
        w.writerow(row)
    return row


def cycle_check(row, t=None):
    """k61-rule.md: not while the day's cycle is in progress, from a stamp at which T1 changed on more than half the
    qubits until 30 minutes after the next stamp at which CZ errors changed on more than half the edges. From
    cycle-61.json: the latest T1 and CZ stamps of the 48-hour walk. Then the snapshot just read (row, from
    record_stamp) is compared by value with the walk's snapshot of that CZ stamp (history 01's compare): if T1 has since
    changed on more than half the qubits, or CZ errors on more than half the edges, a new cycle has begun since the
    walk, and the check does not pass."""
    t = t or datetime.now(timezone.utc)
    cyc = json.loads((HERE / "cycle-61.json").read_text())["cycle"]
    out = {"utc": now(), "latest_T1_stamp_utc": cyc["latest_T1_stamp_utc"], "latest_CZ_stamp_utc": cyc["latest_CZ_stamp_utc"],
           "cycle_complete_in_48h": cyc["cycle_complete_in_48h"], "submissions_from_utc": cyc["submissions_from_utc"], "snapshot_read": row["snapshot"]}
    if not cyc["cycle_complete_in_48h"]:
        return {**out, "pass": False, "reason": "the walk's latest T1 stamp has no CZ stamp after it"}
    f = lambda s: datetime.fromisoformat(s.replace("Z", "+00:00"))
    if t < f(cyc["submissions_from_utc"]):
        return {**out, "pass": False, "reason": "less than 30 minutes after the latest CZ stamp"}
    cz_snap = HERE / "history-61" / "snapshots" / snap_name(cyc["latest_CZ_stamp_utc"])
    c = TH.compare(TH.load(cz_snap), TH.load(STAMPS / row["snapshot"]))
    since = {"q_T1": c["q_T1"], "cz_error": c["cz_error"], "n_edges": c["n_edges"]}
    new_cycle = c["q_T1"] > TH.N_QUBITS / 2 or c["cz_error"] > c["n_edges"] / 2
    return {**out, "changed_since_latest_CZ_stamp": since, "new_cycle_since_walk": new_cycle, "pass": not new_cycle,
            "reason": "a new T1 or CZ step since the walk's latest CZ stamp" if new_cycle else "the day's cycle is complete and no new step has come"}


# --------------------------------------------------------------------------- the circuits
def made(qc, layout, backend, name):
    ins, isa = K51._made(qc, layout, backend)
    return K50.rebuild(isa, ins, name)


def logical(k):
    from qiskit import QuantumCircuit
    if k in ("A", "B"):
        qc = QuantumCircuit(len(QUBITS), len(QUBITS), name=k)
        if k == "B":
            for i in range(len(QUBITS)):
                qc.x(i)
        for i in range(len(QUBITS)):
            qc.measure(i, i)
        return qc
    qc = QuantumCircuit(1, 1, name=k)
    if k == "M-one":
        qc.x(0)
    elif k == "Z":
        qc.h(0)                 # hw_50.logical("Z"): H, H, measure on M, here on M's one line
        qc.h(0)
    qc.measure(0, 0)
    return qc


def three_line(k):
    """The circuit as Kickoffs 50 and 55 wrote it, on the chain's three lines (M = 1, measured into c5): hw_50.logical("Z")
    unchanged, and hw_55's logical_x1 (X on M, measure). Built for the check only, never submitted."""
    from qiskit import QuantumCircuit
    if k == "Z":
        return K50.logical("Z", 0)
    qc = QuantumCircuit(3, W.WAIT_TEST_CLBITS, name="X1")
    qc.x(W.M)
    qc.measure(W.M, K50.M_CLBIT)
    return qc


def layout_of(key):
    k, M = key
    return list(QUBITS) if k in ("A", "B") else [M]


def build(backend):
    circ = {("A", None): made(logical("A"), QUBITS, backend, "A"), ("B", None): made(logical("B"), QUBITS, backend, "B")}
    for M in MS:
        for k in ALONE:
            circ[(k, M)] = made(logical(k), [M], backend, f"{k}-{M}")
    return circ


def ops_of(c, q=None):
    """(name, physical qubits, clbits, delay duration) per instruction, in order; with q, only those on qubit q."""
    out = []
    for i in c.data:
        qs = [c.find_bit(x).index for x in i.qubits]
        if q is not None and q not in qs:
            continue
        out.append((i.operation.name, qs, [c.find_bit(x).index for x in i.clbits],
                    int(i.operation.duration) if i.operation.name == "delay" else None))
    return out


def digest(c):
    """A hash of every instruction in order: name, qubits, clbits and parameters (an rz's angle, a delay's duration)."""
    def par(op):
        try:
            return [round(float(x), 12) for x in op.params]
        except Exception:
            return [str(x) for x in op.params]
    seq = [(i.operation.name, [c.find_bit(x).index for x in i.qubits], [c.find_bit(x).index for x in i.clbits], par(i.operation)) for i in c.data]
    return hashlib.sha256(json.dumps(seq).encode()).hexdigest()


def checks(circ, backend):
    """Section 1's checks 1 and 2 on every circuit."""
    t, dt = backend.target, backend.dt
    rec = {}
    for (k, M), c in circ.items():
        lay = layout_of((k, M))
        ops = {a: int(b) for a, b in c.count_ops().items()}
        init = list(c.layout.initial_index_layout(filter_ancillas=True))
        touched = {q for name, qs, _, _ in ops_of(c) for q in qs}
        p = W.exact_distribution(c)
        r = {"count_ops": ops, "no_swap": ops.get("swap", 0) == 0, "layout_as_named": init == lay, "touches_named_qubits_only": touched == set(lay)}
        tl = K50.timed(K50.instructions(c), t, dt, lay)
        meas = [(nm, qs, cs, s) for _, nm, qs, cs, s, d in tl if nm == "measure"]
        r["measure_qubit_to_clbit"] = {str(qs[0]): cs[0] for nm, qs, cs, s in meas}
        r["measure_start_dt"] = sorted({s for *_, s in meas})
        if k in ("A", "B"):
            r["measures_exactly_the_sixteen"] = sorted(int(q) for q in r["measure_qubit_to_clbit"]) == QUBITS and len(meas) == len(QUBITS)
            r["qubit_i_into_clbit_i"] = all(r["measure_qubit_to_clbit"][str(q)] == i for i, q in enumerate(QUBITS))
            gates = {nm for nm, *_ in ops_of(c) if nm not in ("measure", "delay", "barrier")}
            if k == "A":
                r["no_gate"] = gates == set()
            else:
                xs = [qs[0] for nm, qs, *_ in ops_of(c) if nm == "x"]
                r["one_x_per_qubit"] = sorted(xs) == QUBITS and gates == {"x"}
            r["all_measures_at_one_time"] = len(r["measure_start_dt"]) == 1
            p1 = {str(q): sum(v for key, v in p.items() if key[::-1][i] == "1") for i, q in enumerate(QUBITS)}
            want = 0.0 if k == "A" else 1.0
            r["exact_P1"] = p1
            r["exact_P1_expected"] = want
            r["exact_P1_as_expected"] = all(abs(v - want) < 1e-9 for v in p1.values())
        else:
            p1 = sum(v for key, v in p.items() if key[::-1][0] == "1")
            want = 1.0 if k == "M-one" else 0.0
            r["one_measure_one_clbit"] = ops.get("measure") == 1 and c.num_clbits == 1
            r["exact_P1"] = p1
            r["exact_P1_expected"] = want
            r["exact_P1_as_expected"] = abs(p1 - want) < 1e-9
            gates = [nm for nm, *_ in ops_of(c) if nm not in ("measure", "delay", "barrier")]
            r["M_gates_before_measure"] = gates
            r["gates_as_named"] = {"M-zero": gates == [], "M-one": gates == ["x"], "Z": gates == ["rz", "sx", "rz", "rz", "sx", "rz"]}[k]
            if k in ("M-one", "Z"):
                ch = CHAIN_OF[M]
                c3 = made(three_line(k), ch, backend, f"{k}-{M}-three-line")
                m3 = [(nm, cs) for nm, qs, cs, _ in ops_of(c3, M) if nm != "delay"]
                m1 = [(nm, cs) for nm, qs, cs, _ in ops_of(c, M) if nm != "delay"]
                r["three_line_on_chain"] = {"chain": ch, "other_lines": {str(q): [nm for nm, *_ in ops_of(c3, q)] for q in (ch[0], ch[2])},
                                            "M_ops": [nm for nm, _ in m3]}
                r["M_ops_same_as_three_line"] = [nm for nm, _ in m3] == [nm for nm, _ in m1]
        rec[f"{k}" if M is None else f"{k}|{M}"] = r
    flat = [v for r in rec.values() for v in r.values() if isinstance(v, bool)]
    return rec, all(flat)


def assemble(circ):
    items = [(key, cp) for key in circ for cp in range(1, COPIES + 1)]
    perm = np.random.default_rng(SEEDS["order"]).permutation(len(items))
    circs, labels, shots = [], [], []
    for i in perm:
        (k, M), cp = items[i]
        labels.append({"circuit": k, "M": M, "copy": cp, "qubits": layout_of((k, M)), "clbit_of_qubit": {str(q): j for j, q in enumerate(layout_of((k, M)))},
                       "chain": CHAIN_OF.get(M)})
        circs.append(circ[(k, M)])
        shots.append(SHOTS)
    return circs, labels, shots
